import { Injectable } from '@angular/core';
import { createKalrav } from '../core/kalrav';
import type { KalravConfig, KalravWidget } from '../core/types';

@Injectable({
  providedIn: 'root'
})
export class KalravService {
  private kalravInstance: KalravWidget | null = null;

  initialize(config: KalravConfig): void {
    if (this.kalravInstance) {
      this.kalravInstance.unload();
    }
    this.kalravInstance = createKalrav(config);
  }

  getWidget(): KalravWidget | null {
    return this.kalravInstance;
  }

  open(): void {
    this.kalravInstance?.open();
  }

  close(): void {
    this.kalravInstance?.close();
  }

  isLoaded(): boolean {
    return this.kalravInstance?.isLoaded() ?? false;
  }

  unload(): void {
    this.kalravInstance?.unload();
    this.kalravInstance = null;
  }
}
