import { AGENT_RUNTIME_CONFIG_BASE_URL, getChatApiBaseUrl } from './api-config.js';

/**
 * Send the public widget's existing API configuration to the backend.
 * This request is intentionally fire-and-forget from Kalrav.load().
 */
export async function sendRuntimeConfig(config = {}) {
  if (!config.agentId) return;

  const chatApiBaseUrl = getChatApiBaseUrl(config.chatApiBaseUrl);
  const websiteUrl = new URL(window.location.href);
  const queryUrl = new URL(
    config.queryUrl || `${chatApiBaseUrl}/api/v1/query`,
    window.location.href
  );
  const apiBaseUrl = config.queryUrl
    ? queryUrl.origin
    : chatApiBaseUrl;
  const payload = {
    provider: 'custom',
    website_url: `${websiteUrl.origin}${websiteUrl.pathname}`,
    api_base_url: apiBaseUrl,
    query_path: `/${queryUrl.pathname.replace(/^\/+/, '')}${queryUrl.search}`,
    auth_type: config.apiKey ? 'api_key' : 'none',
    ...(config.apiKey ? { api_key: config.apiKey } : {}),
    enabled: true,
  };
  const url = `${AGENT_RUNTIME_CONFIG_BASE_URL}/${encodeURIComponent(config.agentId)}/runtime-config`;
  const response = await fetch(url, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(payload),
  });

  if (!response.ok) {
    const result = await response.json().catch(() => null);
    throw new Error(result?.error || 'Unable to save agent configuration');
  }
}
