import { Component, Input, OnInit, OnDestroy } from '@angular/core';
import { createKalrav } from '../core/kalrav';
import type { KalravConfig, KalravWidget as KalravWidgetInstance } from '../core/types';

@Component({
  selector: 'kalrav-widget',
  template: '<div style="display:none"></div>',
  standalone: true
})
export class KalravWidget implements OnInit, OnDestroy {
  @Input() apiKey?: string;
  @Input() agentId?: string;
  @Input() primaryColor: string = '#4F46E5';
  @Input() autoLoad: boolean = true;
  @Input() autoOpenWidget?: boolean;
  @Input() emailChatAutoSendEnabled?: boolean;
  @Input() emailChatAutoSendTo?: string;
  @Input() emailChatAutoSendOnClose?: boolean;
  @Input() emailChatAutoSendOnNewSession?: boolean;
  @Input() agentType?: string;
  @Input() agentUiData?: Record<string, any>;
  @Input() agentUiSettings?: Record<string, any>;
  @Input() agentUiSettingsUrl?: string;
  @Input() queryUrl?: string;
  @Input() chatApiBaseUrl?: string;
  @Input() centralSystemBaseUrl?: string;
  @Input() queryHeaders?: Record<string, string>;
  @Input() fetchAgentUiSettings?: KalravConfig['fetchAgentUiSettings'];
  @Input() queryFetcher?: KalravConfig['queryFetcher'];
  @Input() queryRequestMapper?: KalravConfig['queryRequestMapper'];
  @Input() queryResponseMapper?: KalravConfig['queryResponseMapper'];
  @Input() analyticsUserId?: string;

  private kalravInstance: KalravWidgetInstance | null = null;

  ngOnInit(): void {
    this.kalravInstance = createKalrav({
      apiKey: this.apiKey,
      agentId: this.agentId,
      primaryColor: this.primaryColor,
      autoLoad: this.autoLoad,
      autoOpenWidget: this.autoOpenWidget,
      emailChatAutoSendEnabled: this.emailChatAutoSendEnabled,
      emailChatAutoSendTo: this.emailChatAutoSendTo,
      emailChatAutoSendOnClose: this.emailChatAutoSendOnClose,
      emailChatAutoSendOnNewSession: this.emailChatAutoSendOnNewSession,
      agentType: this.agentType,
      agentUiData: this.agentUiData,
      agentUiSettings: this.agentUiSettings,
      agentUiSettingsUrl: this.agentUiSettingsUrl,
      queryUrl: this.queryUrl,
      chatApiBaseUrl: this.chatApiBaseUrl,
      centralSystemBaseUrl: this.centralSystemBaseUrl,
      queryHeaders: this.queryHeaders,
      fetchAgentUiSettings: this.fetchAgentUiSettings,
      queryFetcher: this.queryFetcher,
      queryRequestMapper: this.queryRequestMapper,
      queryResponseMapper: this.queryResponseMapper,
      analyticsUserId: this.analyticsUserId,
    });
  }

  ngOnDestroy(): void {
    this.kalravInstance?.unload();
    this.kalravInstance = null;
  }
}
