import type { KalravConfig, KalravWidget } from './types';
// @ts-ignore - ConfigManager is JS file
import { ConfigManager } from '../config-manager.js';
// @ts-ignore - Runtime configuration sender is a JS file
import { sendRuntimeConfig } from '../runtime-config.js';

const HOSTED_WIDGET_URL = 'https://widget.kalrav.ai/routeye-widget.js';
const DEFAULT_PRIMARY_COLOR = '#4F46E5';

/**
 * Kalrav AI Widget Core Implementation
 * 
 * This is the core vanilla JS/TS implementation that works across all frameworks.
 * Enhanced version of the original kalravPureJs.js with TypeScript support.
 */
export class Kalrav implements KalravWidget {
  private loaded: boolean = false;
  private script: HTMLScriptElement | null = null;
  private runtimeConfigSent: boolean = false;
  private lifecycleVersion: number = 0;
  private readonly instanceId: string;
  private config: KalravConfig & { primaryColor: string; autoLoad: boolean };

  constructor(config: KalravConfig) {
    this.instanceId = `kalrav-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
    this.config = {
      ...config,
      primaryColor: config.primaryColor || DEFAULT_PRIMARY_COLOR,
      autoLoad: config.autoLoad !== false,
    };

    // Auto-load if enabled
    if (this.config.autoLoad && typeof window !== 'undefined') {
      this.load().catch((err) => {
        console.warn('Kalrav auto-load failed:', err);
      });
    }
  }

  /**
   * Remove broken or duplicate scripts
   */
  private removeStaleScripts(): void {
    if (typeof document === 'undefined') return;

    document.querySelectorAll('script[src*="routeye-widget.js"]').forEach((s) => {
      const hasAgent = !!s.getAttribute('data-agent-id');
      const hasKey = !!(s.getAttribute('data-x-key') || (s as HTMLElement).dataset.xKey);

      if (!hasAgent || !hasKey) {
        console.warn('Kalrav: Removing stale script:', s.outerHTML);
        s.remove();
      }
    });
  }

  /**
   * Load the Kalrav widget
   */
  public async load(): Promise<void> {
    if (typeof window === 'undefined') {
      throw new Error('Kalrav: Cannot load in non-browser environment');
    }

    if (typeof document === 'undefined') {
      throw new Error('Kalrav: Document is not available');
    }

    // Check if already loaded
    if (this.loaded) {
      return Promise.resolve();
    }

    const lifecycleVersion = ++this.lifecycleVersion;

    // Send existing public API configuration without delaying widget startup.
    if (!this.runtimeConfigSent && this.config.agentId) {
      this.runtimeConfigSent = true;
      void sendRuntimeConfig(this.config).catch(() => {});
    }

    return new Promise((resolve, reject) => {
      try {
        // 🎨 UI customization config will be fetched by widget.js itself
        // We just need to create a script tag with the agent credentials
        
        const script = document.createElement('script');
        
        script.src = HOSTED_WIDGET_URL;
        script.setAttribute('data-kalrav-instance-id', this.instanceId);
        
        if (this.config.agentId) script.setAttribute('data-agent-id', this.config.agentId);
        if (this.config.apiKey) script.setAttribute('data-x-key', this.config.apiKey);
        script.setAttribute('data-primary-color', this.config.primaryColor);
        if (this.config.agentType) script.setAttribute('data-agent-type', this.config.agentType);
        if (this.config.agentUiData) script.setAttribute('data-agent-ui-data', JSON.stringify(this.config.agentUiData));
        if (this.config.agentUiSettingsUrl) script.setAttribute('data-agent-ui-settings-url', this.config.agentUiSettingsUrl);
        if (this.config.queryUrl) script.setAttribute('data-query-url', this.config.queryUrl);
        if (this.config.chatApiBaseUrl) script.setAttribute('data-chat-api-base-url', this.config.chatApiBaseUrl);
        if (this.config.centralSystemBaseUrl) script.setAttribute('data-central-system-base-url', this.config.centralSystemBaseUrl);
        if (this.config.analyticsUserId) script.setAttribute('data-analytics-user-id', this.config.analyticsUserId);
        if (this.config.autoOpenWidget !== undefined) script.setAttribute('data-auto-open', String(this.config.autoOpenWidget));
        if (this.config.emailChatAutoSendEnabled !== undefined) script.setAttribute('data-email-chat-auto-send', String(this.config.emailChatAutoSendEnabled));
        if (this.config.emailChatAutoSendTo) script.setAttribute('data-email-chat-auto-send-to', this.config.emailChatAutoSendTo);
        if (this.config.emailChatAutoSendOnClose !== undefined) script.setAttribute('data-email-chat-auto-send-on-close', String(this.config.emailChatAutoSendOnClose));
        if (this.config.emailChatAutoSendOnNewSession !== undefined) script.setAttribute('data-email-chat-auto-send-on-new-session', String(this.config.emailChatAutoSendOnNewSession));
        const runtimeConfig = {
          agentUiSettings: this.config.agentUiSettings,
          fetchAgentUiSettings: this.config.fetchAgentUiSettings,
          queryHeaders: this.config.queryHeaders,
          queryFetcher: this.config.queryFetcher,
          queryRequestMapper: this.config.queryRequestMapper,
          queryResponseMapper: this.config.queryResponseMapper,
          emailChatAutoSendEnabled: this.config.emailChatAutoSendEnabled,
          emailChatAutoSendTo: this.config.emailChatAutoSendTo,
          emailChatAutoSendOnClose: this.config.emailChatAutoSendOnClose,
          emailChatAutoSendOnNewSession: this.config.emailChatAutoSendOnNewSession,
        };
        const kalravWindow = window as any;
        kalravWindow.KalravWidgetConfigs = {
          ...kalravWindow.KalravWidgetConfigs,
          [this.instanceId]: runtimeConfig,
        };
        // Keep the original global config for direct-script and older-runtime compatibility.
        kalravWindow.KalravWidgetConfig = {
          ...kalravWindow.KalravWidgetConfig,
          ...runtimeConfig,
        };
        script.async = false;

        script.onload = () => {
          if (lifecycleVersion !== this.lifecycleVersion || !script.isConnected) {
            resolve();
            return;
          }
          this.script = script;
          this.loaded = true;
          console.log('✅ Kalrav widget loaded successfully');
          resolve();
        };

        script.onerror = (e) => {
          if (lifecycleVersion !== this.lifecycleVersion) {
            resolve();
            return;
          }
          this.loaded = false;
          script.remove();

          console.error('❌ Kalrav widget failed to load', e);
          reject(new Error('Failed to load Kalrav widget script'));
        };

        document.body.appendChild(script);
        this.script = script;
      } catch (err) {
        this.loaded = false;
        reject(err);
      }
    });
  }

  /**
   * Unload the widget
   */
  public unload(): void {
    this.lifecycleVersion += 1;
    const script = this.script;
    script?.remove();

    this.script = null;
    this.loaded = false;

    // Optional cleanup
    if (typeof window !== 'undefined') {
      try {
        delete (window as any).routeyeWidget;
        const configs = (window as any).KalravWidgetConfigs;
        if (configs) {
          delete configs[this.instanceId];
        }
      } catch (_) {
        // Ignore errors
      }
    }

    if (typeof document !== 'undefined') {
      const root = document.getElementById('routeye-widget-root');
      const rootOwner = root?.getAttribute('data-kalrav-instance-id');
      if (root && (!rootOwner || rootOwner === this.instanceId)) {
        root.remove();
      }
    }

  }

  /**
   * Open the chat widget
   */
  public open(): void {
    if (typeof window === 'undefined') return;

    const w = window as any;
    if (w.routeyeWidget?.open) {
      return w.routeyeWidget.open();
    }

    w.dispatchEvent(new CustomEvent('kalrav:open'));
  }

  /**
   * Close the chat widget
   */
  public close(): void {
    if (typeof window === 'undefined') return;

    const w = window as any;
    if (w.routeyeWidget?.close) {
      return w.routeyeWidget.close();
    }

    w.dispatchEvent(new CustomEvent('kalrav:close'));
  }

  /**
   * Check if widget is loaded
   */
  public isLoaded(): boolean {
    return this.loaded;
  }

  /**
   * Call any widget method
   */
  public call(method: string, ...args: any[]): void {
    if (typeof window === 'undefined') return;

    const w = window as any;
    if (w.routeyeWidget?.[method]) {
      return w.routeyeWidget[method](...args);
    }

    w.dispatchEvent(
      new CustomEvent('kalrav:call', { detail: { method, args } })
    );
  }
}

/**
 * Factory function to create a new Kalrav instance
 */
export function createKalrav(config: KalravConfig): KalravWidget {
  return new Kalrav(config);
}
