import apiConfig from '../api-config.json';

export const CHAT_API_BASE_URL = apiConfig.chatApiBaseUrl;

export const CENTRAL_SYSTEM_BASE_URL = apiConfig.centralSystemBaseUrl;
export const CENTRAL_SYSTEM_API_BASE_URL = `${CENTRAL_SYSTEM_BASE_URL}/api`;
export const AGENT_UI_CONFIG_API_BASE_URL = `${CENTRAL_SYSTEM_API_BASE_URL}/agent-ui`;
export const AGENT_RUNTIME_CONFIG_BASE_URL = apiConfig.agentRuntimeConfigBaseUrl;
export const DEFAULT_LOGO_URL = apiConfig.defaultLogoUrl;

function trimTrailingSlash(value) {
  return typeof value === 'string' ? value.replace(/\/+$/, '') : value;
}

export function getChatApiBaseUrl(override) {
  return trimTrailingSlash(override || CHAT_API_BASE_URL);
}

export function getCentralSystemBaseUrl(override) {
  return trimTrailingSlash(override || CENTRAL_SYSTEM_BASE_URL);
}

export function getCentralSystemApiBaseUrl(override) {
  return `${getCentralSystemBaseUrl(override)}/api`;
}

export function getAgentUiConfigApiBaseUrl(override) {
  return override
    ? `${getCentralSystemApiBaseUrl(override)}/agent-ui`
    : AGENT_UI_CONFIG_API_BASE_URL;
}
